"""Tests use a design JSON generated by NeqSim (tests/fixtures/sample_design.json), so no JVM is needed."""

import json
import math
from pathlib import Path

import pytest

from umbilical_design import (
    FigureMeta,
    UmbilicalSpec,
    captions,
    cross_section_layout,
    findings,
    key_numbers,
    load_result,
    pack_circles,
    render_all,
    write_handoff,
)

FIXTURE = Path(__file__).parent / "fixtures" / "sample_design.json"


@pytest.fixture()
def result():
    return load_result(FIXTURE)


def test_load_result_rejects_foreign_json():
    with pytest.raises(ValueError, match="missing sections"):
        load_result({"configuration": {}})


def test_fixture_is_an_accepted_design(result):
    assert result.accepted
    assert result.length_m == pytest.approx(15000.0)
    assert len(result.fluid_lines) == 5
    assert "lineFrictionDropWithinPressureBudget" in result.checks


def test_pack_circles_has_no_overlap_and_encloses(result):
    diameters = [3.0, 10.0, 10.0, 10.0, 25.0, 6.0]
    placed, (cx, cy, radius) = pack_circles(diameters)
    for i, a in enumerate(placed):
        assert math.hypot(a.x - cx, a.y - cy) + a.radius <= radius + 1e-6
        for b in placed[i + 1:]:
            assert math.hypot(a.x - b.x, a.y - b.y) >= a.radius + b.radius - 1e-6
    area = sum(math.pi * (d / 2) ** 2 for d in diameters)
    assert math.pi * radius**2 >= area


def test_three_equal_circles_pack_like_the_theory():
    placed, (_, _, radius) = pack_circles([10.0, 10.0, 10.0])
    # three touching equal circles: enclosing diameter is d (1 + 2/sqrt(3)) = 2.155 d
    assert 2.0 * radius == pytest.approx(10.0 * (1 + 2 / math.sqrt(3)), rel=0.01)


def test_layout_agrees_with_neqsim_bundle_estimate(result):
    layout = cross_section_layout(result)
    assert 0.8 < layout["packing_ratio"] < 1.15
    assert layout["overall_radius"] * 2 == pytest.approx(result.result("calculatedOuterDiameterMm"))
    assert len(layout["armor_wires"]) > 20


def test_key_numbers_are_traceable(result):
    numbers = key_numbers(result)
    assert numbers["umbilical_length_km"]["value"] == pytest.approx(15.0)
    assert all({"value", "unit", "source"} <= set(v) for v in numbers.values())
    assert "umbilical_meg_friction_drop_bar" in numbers


def test_functional_checks_reach_key_numbers_and_findings(result):
    numbers = key_numbers(result)
    assert numbers["umbilical_weight_ratio"]["value"] > 1.5
    assert numbers["umbilical_optical_budget_db"]["unit"] == "dB"
    assert numbers["umbilical_meg_fill_volume_l"]["value"] == pytest.approx(7600.0, rel=0.01)
    assert numbers["umbilical_meg_displacement_time_h"]["value"] == pytest.approx(15.2, rel=0.01)
    data = json.loads(FIXTURE.read_text(encoding="utf-8"))
    for line in data["elementResults"]:
        if line["name"] == "Scale inhibitor":
            line["displacementTimeHours"] = 120.0
    data["calculatedResults"]["weightRatio"] = 1.1
    notes = findings(load_result(data))
    assert any("displace" in n and "Scale inhibitor" in n for n in notes)
    assert any("Weight ratio" in n for n in notes)


def test_findings_flag_a_failed_check_and_a_hot_line(result):
    data = json.loads(FIXTURE.read_text(encoding="utf-8"))
    data["designChecks"]["armorCapacityCoversDesignTension"] = False
    for line in data["elementResults"]:
        if line["name"] == "MEG":
            line["frictionDropBar"] = 250.0
    notes = findings(load_result(data))
    assert any(n.startswith("FAIL") and "Armour" in n for n in notes)
    assert any("MEG" in n and "friction drop" in n for n in notes)


def test_captions_carry_the_numbers(result):
    text = captions(result)
    assert "84.2" in text["cross_section"] or "mm" in text["cross_section"]
    assert "electrical" in text


def test_render_all_writes_figures_and_handoff(result, tmp_path):
    spec = UmbilicalSpec.from_dict(
        {
            "name": "Synthetic",
            "length_km": 15.0,
            "water_depth_m": 100.0,
            "lines": [{"name": "MEG", "kind": "chemical", "inner_diameter_mm": 25.4, "design_pressure_bar": 345.0}],
            "evidence": {"water_depth": "screening default"},
        }
    )
    paths = write_handoff(result, tmp_path, spec, FigureMeta("Synthetic umbilical", "test basis"))
    for key in ("cross_section", "hydraulics", "mechanical", "checks", "on_a_page", "electrical", "handoff", "key_numbers"):
        assert paths[key].is_file() and paths[key].stat().st_size > 0
    handoff = paths["handoff"].read_text(encoding="utf-8")
    assert "Basis version used = test basis" in handoff
    assert "screening default" in handoff
    assert "Open items" in handoff
    figures = render_all(result, tmp_path / "again", FigureMeta("x"))
    assert figures["on_a_page"].with_suffix(".pdf").is_file()


def test_spec_requires_length_depth_and_elements():
    with pytest.raises(ValueError):
        UmbilicalSpec.from_dict({"water_depth_m": 100.0, "lines": []})
    with pytest.raises(ValueError, match="missing"):
        UmbilicalSpec.from_common_basis({"umbilical": {"lines": []}})
    with pytest.raises(ValueError, match="no 'umbilical' block"):
        UmbilicalSpec.from_common_basis({})


def test_spec_from_common_basis_reads_block():
    basis = {
        "created": "2026-11-13T02:17:55",
        "umbilical": {
            "length_km": 15.0,
            "water_depth_m": 95.0,
            "lines": [{"name": "LP", "kind": "hydraulic", "inner_diameter_mm": 9.5, "design_pressure_bar": 345}],
            "cables": [{"name": "Power", "cores": 3, "voltage_v": 3300}],
        },
    }
    spec = UmbilicalSpec.from_common_basis(basis)
    assert spec.length_m == 15000.0 and spec.cables[0].conductor_area_mm2 is None
